create table if not exists public.players(id uuid primary key references auth.users(id) on delete cascade,display_name text not null,age int not null default 21,gender text not null default 'Other',money numeric(14,2) not null default 50000,bank_balance numeric(14,2) not null default 0,health int not null default 100,happiness int not null default 70,energy int not null default 100,reputation int not null default 10,district text not null default 'gwarinpa',job text not null default 'Job Seeker',job_salary numeric(14,2) not null default 0,housing text not null default 'Shared Apartment',housing_cost numeric(14,2) not null default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.activity_log(id uuid primary key default gen_random_uuid(),player_id uuid references public.players(id) on delete cascade,action text not null,amount numeric(14,2) default 0,details text,created_at timestamptz default now());
alter table public.players enable row level security;alter table public.activity_log enable row level security;
drop policy if exists players_select on public.players;create policy players_select on public.players for select using(auth.uid()=id);
drop policy if exists players_insert on public.players;create policy players_insert on public.players for insert with check(auth.uid()=id);
drop policy if exists players_update on public.players;create policy players_update on public.players for update using(auth.uid()=id);
drop policy if exists activity_select on public.activity_log;create policy activity_select on public.activity_log for select using(auth.uid()=player_id);
drop policy if exists activity_insert on public.activity_log;create policy activity_insert on public.activity_log for insert with check(auth.uid()=player_id);
